typedef struct {
  int *data;
  int size;
} SortedStack;

SortedStack *sortedStackCreate(void) {
  SortedStack *obj = (SortedStack *)malloc(sizeof(SortedStack));
  obj->data = (int *)malloc(sizeof(int) * 200000);
  obj->size = 0;
  return obj;
}

void sortedStackPush(SortedStack *obj, int val) {
  int *tmp = (int *)malloc(sizeof(int) * (obj->size + 1));
  int t = 0;
  while (obj->size > 0 && obj->data[obj->size - 1] < val) {
    tmp[t++] = obj->data[--obj->size];
  }
  obj->data[obj->size++] = val;
  while (t > 0) {
    obj->data[obj->size++] = tmp[--t];
  }
  free(tmp);
}

void sortedStackPop(SortedStack *obj) {
  if (obj->size > 0) obj->size--;
}

int sortedStackPeek(SortedStack *obj) {
  return obj->size > 0 ? obj->data[obj->size - 1] : -1;
}

bool sortedStackIsEmpty(SortedStack *obj) {
  return obj->size == 0;
}

void sortedStackFree(SortedStack *obj) {
  free(obj->data);
  free(obj);
}

class SortedStack {
  stack<int> data;

public:
  SortedStack() {}
  void push(int val) {
    stack<int> tmp;
    while (!data.empty() && data.top() < val) {
      tmp.push(data.top());
      data.pop();
    }
    data.push(val);
    while (!tmp.empty()) {
      data.push(tmp.top());
      tmp.pop();
    }
  }
  void pop() {
    if (!data.empty()) data.pop();
  }
  int peek() { return data.empty() ? -1 : data.top(); }
  bool isEmpty() { return data.empty(); }
};

type SortedStack struct {
	data []int
}

func Constructor() SortedStack {
	return SortedStack{}
}

func (s *SortedStack) Push(val int) {
	var tmp []int
	for len(s.data) > 0 && s.data[len(s.data)-1] < val {
		tmp = append(tmp, s.data[len(s.data)-1])
		s.data = s.data[:len(s.data)-1]
	}
	s.data = append(s.data, val)
	for len(tmp) > 0 {
		s.data = append(s.data, tmp[len(tmp)-1])
		tmp = tmp[:len(tmp)-1]
	}
}

func (s *SortedStack) Pop() {
	if len(s.data) > 0 {
		s.data = s.data[:len(s.data)-1]
	}
}

func (s *SortedStack) Peek() int {
	if len(s.data) == 0 {
		return -1
	}
	return s.data[len(s.data)-1]
}

func (s *SortedStack) IsEmpty() bool {
	return len(s.data) == 0
}

class SortedStack {
  private Deque<Integer> data = new ArrayDeque<>();

  public SortedStack() {}

  public void push(int val) {
    Deque<Integer> tmp = new ArrayDeque<>();
    while (!data.isEmpty() && data.peek() < val) tmp.push(data.pop());
    data.push(val);
    while (!tmp.isEmpty()) data.push(tmp.pop());
  }

  public void pop() {
    if (!data.isEmpty()) data.pop();
  }

  public int peek() {
    return data.isEmpty() ? -1 : data.peek();
  }

  public boolean isEmpty() {
    return data.isEmpty();
  }
}

class SortedStack:
    def __init__(self):
        self.data = []

    def push(self, val: int) -> None:
        tmp = []
        while self.data and self.data[-1] < val:
            tmp.append(self.data.pop())
        self.data.append(val)
        while tmp:
            self.data.append(tmp.pop())

    def pop(self) -> None:
        if self.data:
            self.data.pop()

    def peek(self) -> int:
        return self.data[-1] if self.data else -1

    def isEmpty(self) -> bool:
        return not self.data

impl SortedStack {
  pub fn new() -> Self {
    SortedStack { data: vec![] }
  }

  pub fn push(&mut self, val: i32) {
    let mut tmp = vec![];
    while let Some(&top) = self.data.last() {
      if top < val {
        tmp.push(self.data.pop().unwrap());
      } else {
        break;
      }
    }
    self.data.push(val);
    while let Some(v) = tmp.pop() {
      self.data.push(v);
    }
  }

  pub fn pop(&mut self) {
    self.data.pop();
  }

  pub fn peek(&self) -> i32 {
    *self.data.last().unwrap_or(&-1)
  }

  pub fn is_empty(&self) -> bool {
    self.data.is_empty()
  }
}

class SortedStack {
  private data: number[] = [];

  push(val: number): void {
    const tmp: number[] = [];
    while (this.data.length > 0 && this.data[this.data.length - 1] < val) {
      tmp.push(this.data.pop()!);
    }
    this.data.push(val);
    while (tmp.length > 0) this.data.push(tmp.pop()!);
  }

  pop(): void {
    if (this.data.length > 0) this.data.pop();
  }

  peek(): number {
    return this.data.length > 0 ? this.data[this.data.length - 1] : -1;
  }

  isEmpty(): boolean {
    return this.data.length === 0;
  }
}
